function useNarrowScreen(){const [compact,setCompact]=useState(()=>typeof matchMedia==='function'&&matchMedia('(max-width:650px)').matches);useEffect(()=>{const media=matchMedia('(max-width:650px)');const on=()=>setCompact(media.matches);media.addEventListener('change',on);return()=>media.removeEventListener('change',on)},[]);return compact}
